import sys


def one_best(prices, i, j):
    if i >= j:
        return 0
    best = 0
    mn = prices[i]
    for k in range(i, j + 1):
        best = max(best, prices[k] - mn)
        mn = min(mn, prices[k])
    return best


def max_profit_brute(prices):
    n = len(prices)
    ans = 0
    for m in range(n):
        ans = max(ans, one_best(prices, 0, m) + one_best(prices, m + 1, n - 1))
    return ans


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    prices = list(map(int, data[1:1 + n]))
    print(max_profit_brute(prices))
